import itertools

def check_m(m):
    # All multisets of size m from {0, ..., m-1}
    # A multiset can be represented as a sorted tuple
    from itertools import combinations_with_replacement

    for residues in combinations_with_replacement(range(m), m):
        # Condition 1: sum(residues) % m == 0
        if sum(residues) % m == 0:
            continue

        # Condition 2: exists permutation sigma of (1, ..., m) such that sum(i * residues[sigma(i)-1]) % m == 0
        # Wait, the permutation is of the elements of the multiset.
        # The residues are already the values. Let's say residues are r_1, ..., r_m.
        # We want to know if there's a permutation k_1, ..., k_m of r_1, ..., r_m
        # such that sum_{i=1}^m i * k_i % m == 0.

        found = False
        # We need to permute the residues. Since they can be the same,
        # we use set(itertools.permutations(residues)) to avoid redundant checks.
        for p in set(itertools.permutations(residues)):
            s = sum((i + 1) * p[i] for i in range(m))
            if s % m == 0:
                found = True
                break

        if not found:
            return False
    return True

for m in range(2, 21):
    if check_m(m):
        print(f"{m} works")
    else:
        print(f"{m} does not work")
        break

