import itertools

def check_m_final(m):
    # Use the property: for a given multiset, we want to know if there exists a permutation
    # such that sum(i * k_i) % m == 0.
    # This is equivalent to the following:
    # Is there a way to partition {1, ..., m} into sets S_r of size c_r
    # such that sum_{r=0}^{m-1} r * (sum_{i in S_r} i) % m == 0.

    from itertools import combinations_with_replacement

    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        counts = [0] * m
        for r in residues:
            counts[r] += 1

        # dp[r][mask][s] where r is residue, mask is used indices, s is current sum
        # To make it faster, we use dp[r][mask] = set of possible sums.
        # But mask is still 2^m. Let's use m up to 15.

        memo = {}

        def dp(r, mask, s):
            if r == m:
                return s == 0
            if counts[r] == 0:
                return dp(r + 1, mask, s)

            state = (r, mask, s)
            if state in memo:
                return memo[state]

            # We need to pick counts[r] indices from the available indices in mask.
            available_indices = [i for i in range(m) if not (mask & (1 << i))]

            for combo in itertools.combinations(available_indices, counts[r]):
                new_mask = mask
                new_sum = s
                for idx in combo:
                    new_mask |= (1 << idx)
                    new_sum = (new_sum + r * (idx + 1)) % m

                if dp(r + 1, new_mask, new_sum):
                    memo[state] = True
                    return True

            memo[state] = False
            return False

        if not dp(0, 0, 0):
            return residues
    return None

