def check_multiset_fast(m, target_counts):
    # target_counts is a tuple of counts for each residue 0, ..., m-1
    # dp[s][counts_tuple] = is it possible?
    # But we can just use dp[counts_tuple] = set of possible sums.

    # The counts_tuple is a tuple of length m.
    # However, we only care about residues that have target_counts[r] > 0.
    active_residues = [r for r in range(m) if target_counts[r] > 0]
    num_active = len(active_residues)

    # dp[counts_tuple] = set of possible sums mod m
    dp = { (0,) * num_active : {0} }

    # We will iterate through the indices i = 1, 2, ..., m
    for i in range(1, m + 1):
        new_dp = {}
        for counts_tuple, sums in dp.items():
            for idx, r in enumerate(active_residues):
                if counts_tuple[idx] < target_counts[r]:
                    new_counts = list(counts_tuple)
                    new_counts[idx] += 1
                    new_counts = tuple(new_counts)

                    if new_counts not in new_dp:
                        new_dp[new_counts] = set()

                    for s in sums:
                        new_dp[new_counts].add((s + r * i) % m)
        dp = new_dp

    target_counts_tuple = tuple(target_counts[r] for r in active_residues)
    return 0 in dp.get(target_counts_tuple, set())

