def count_prime_powers(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False

    prime_powers = set()
    for p in primes:
        power = p
        while power <= limit:
            prime_powers.add(power)
            power *= p
    return len(prime_powers)

