import itertools

def check_m_final_v2(m):
    # For a given multiset, we want to see if there is a permutation
    # such that sum(i * k_i) % m == 0.
    # Instead of all permutations, we use the fact that we only care about
    # the multiset of residues.

    from itertools import combinations_with_replacement

    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        # Check if there is a permutation such that sum(i * k_i) % m == 0.
        # Use DP: dp[i][s] = possible sums using the first i indices.
        # We need to pick residues from the multiset.

        counts = [0] * m
        for r in residues:
            counts[r] += 1

        # dp[i][s] = possible ways to choose i residues from the multiset to have sum s.
        # But we need to know which residues are used.
        # Use dp[i][s][tuple_of_counts_of_residues_used]

        dp = { (0,) * m : {0} }
        for i in range(1, m + 1):
            new_dp = {}
            for counts_used, sums in dp.items():
                for r in range(m):
                    if counts_used[r] < counts[r]:
                        new_counts = list(counts_used)
                        new_counts[r] += 1
                        new_counts = tuple(new_counts)
                        if new_counts not in new_dp:
                            new_dp[new_counts] = set()
                        for s in sums:
                            new_dp[new_counts].add((s + r * i) % m)
            dp = new_dp

        if 0 not in dp.get(tuple(counts), set()):
            return True # This multiset fails
    return False # No multiset fails

