def check_m_fast_v3(m):
    from itertools import combinations_with_replacement

    def check_multiset(counts):
        # dp[i][s] = set of possible sums using i indices
        # But we need to know which residues are used.
        # Let's use the "partitioning {1, ..., m}" idea.
        # dp[r][mask] = set of possible sums using residues 0, ..., r

        active_residues = [r for r in range(m) if counts[r] > 0]

        # dp[residue_idx][mask] = set of possible sums
        dp = {0: {0}} # (mask, sum)
        # Wait, let's use dp[residue_idx][mask] = set of possible sums

        # dp[idx][mask] where idx is the index in active_residues
        # current_dp[mask] = set of sums
        current_dp = {0: {0}}

        for r_idx, r in enumerate(active_residues):
            next_dp = {}
            num_to_pick = counts[r]

            for mask, sums in current_dp.items():
                # We need to pick num_to_pick indices from the available indices (not in mask)
                available = [i for i in range(m) if not (mask & (1 << i))]
                for combo in itertools.combinations(available, num_to_pick):
                    new_mask = mask
                    new_sum_offset = 0
                    for idx in combo:
                        new_mask |= (1 << idx)
                        new_sum_offset = (new_sum_offset + r * (idx + 1)) % m

                    if new_mask not in next_dp:
                        next_dp[new_mask] = set()
                    for s in sums:
                        next_dp[new_mask].add((s + new_sum_offset) % m)
            current_dp = next_dp

        return 0 in current_dp.get((1 << m) - 1, set())

    for residues in combinations_with_replacement(range(m), m):
        if sum(residues) % m == 0:
            continue

        counts = [0] * m
        for r in residues:
            counts[r] += 1

        if not check_multiset(counts):
            return True
    return False

